
import { Component, inject } from '@angular/core';
import { RouterLink } from '@angular/router';
import {
  IonButton,
  IonCol,
  IonContent,
  IonGrid,
  IonIcon,
  IonList,
  IonRow,
  Platform,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import {
  enterOutline,
  logoApple,
  logoGoogle,
  mailOutline,
} from 'ionicons/icons';
import {
  getLoginRoutePath,
  getRoutePath,
  loginEmailRoutePath,
  publicRoutePath,
  signupRoutePath,
} from '../app.routes';
import { AuthService } from '../common/auth/auth.service';
import { ConfigService } from '../common/config/config.service';
import { LogoComponent } from '../common/logo/logo.component';

@Component({
    selector: 'app-login',
    templateUrl: './login.page.html',
    styleUrls: ['./login.page.scss'],
    imports: [
    IonContent,
    IonList,
    IonButton,
    IonIcon,
    IonGrid,
    IonRow,
    IonCol,
    RouterLink,
    LogoComponent
]
})
export class LoginPage {
  private readonly authService = inject(AuthService);
  private readonly configService = inject(ConfigService);
  private readonly platform = inject(Platform);

  readonly publicRoutePath = getRoutePath(publicRoutePath);
  readonly loginWithEmailRouterLink = [getLoginRoutePath(loginEmailRoutePath)];
  readonly signUpRouterLink = [getRoutePath(signupRoutePath)];

  showSignInWithApple = this.getShowSignInWithApple();
  showSignInWithGoogle = this.getShowSignInWithGoogle();

  signUp = false;

  get signUpOrContinue() {
    return this.signUp ? 'Sign up' : 'Continue';
  }

  constructor() {
    addIcons({ mailOutline, logoApple, logoGoogle, enterOutline });
  }

  async loginWithApple(): Promise<any> {
    await this.authService.signInWithApple();
  }

  async loginWithGoogle(): Promise<any> {
    await this.authService.signInWithGoogle();
  }

  private getShowSignInWithApple() {
    const config = this.configService.getConfig();

    if (this.platform.is('android')) {
      return false;
    }

    if (this.platform.is('ios')) {
      return !!config?.appId;
    }

    if (this.platform.is('desktop')) {
      return true;
    }

    return false;
  }

  private getShowSignInWithGoogle() {
    const config = this.configService.getConfig();

    if (this.platform.is('android')) {
      return !!config?.plugins?.SocialLogin?.google?.webClientId;
    }

    if (this.platform.is('ios')) {
      return !!config?.plugins?.SocialLogin?.google?.iOSClientId;
    }

    if (this.platform.is('desktop')) {
      return !!config?.plugins?.SocialLogin?.google?.webClientId;
    }

    return false;
  }
}
